function checkZeroOnes(s) {
  let longestOnes = 0;
  let longestZeros = 0;
  let run = 0;

  for (let i = 0; i < s.length; i++) {
    if (i > 0 && s[i] === s[i - 1]) {
      run++;
    } else {
      run = 1;
    }
    if (s[i] === '1') {
      longestOnes = Math.max(longestOnes, run);
    } else {
      longestZeros = Math.max(longestZeros, run);
    }
  }
  return longestOnes > longestZeros;
}

