function checkZeroOnes(s) {
  const longest = (ch) => {
    let best = 0;
    for (let start = 0; start < s.length; start++) {
      let end = start;
      while (end < s.length && s[end] === ch) end++;
      best = Math.max(best, end - start);
    }
    return best;
  };
  return longest('1') > longest('0');
}

