function generate(rand, size) {
  const n = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 12);
  // Build the string from runs so long segments of both characters appear.
  const maxRun = size === 'large' ? 1 + Math.floor(rand() * 12) : 1 + Math.floor(rand() * 4);
  const bias = rand();
  let s = '';
  let ch = rand() < 0.5 ? '0' : '1';
  while (s.length < n) {
    const limit = ch === '1' ? Math.max(1, Math.round(maxRun * (0.5 + bias))) : Math.max(1, Math.round(maxRun * (1.5 - bias)));
    const len = 1 + Math.floor(rand() * limit);
    s += ch.repeat(Math.min(len, n - s.length));
    ch = rand() < 0.85 ? (ch === '1' ? '0' : '1') : ch;
  }
  return [s];
}
